    "short_description": "925 Ayar Gümüş 24k Altın Kaplama",
    "description": "Frida Kahlo \nRengin ve cesaretin ince bir çizgide buluştuğu parça. Frida Kahlo, adını aldığı dünyadan ilhamla heykelsi bir forma sahip: kıvrım ve köşenin dengesi boyunda fırça darbesi gibi bir iz bırakır. Işığı yüzeyde gezdirerek parlamaktan çok anlatır; yaklaştıkça ortaya çıkan küçük detaylar, tasarıma karakter katar. Beyaz gömlekle yalın ve zarif, desenli bir elbiseyle ifade gücü yüksek—günün ruhuna göre dönüşür. Gösterişe ihtiyaç duymadan dikkat çekmek isteyenler için; her takışta “kendi hikâyesini” anlatan, modern ve özgün bir imza. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
