    "description": "Nidha \nSessizce gelen şıklık. Nidha’nın akıcı hattı, boyunda ince bir iz gibi süzülür; ışık üzerindeyken parlamaktan çok yumuşakça nefes alır. Gözü yormayan bu denge onu sabah işe, öğleden sonra kahveye, akşam bir davete aynı rahatlıkla eşlik eden parça yapar. Ince örgülü bir zincirle sakin ve zarif durur; daha dolgun bir zincirle karakteri belirginleşir. Gardırobunda “her güne olur” kutusuna girecek kadar kullanışlı, yakından bakıldığında ise küçük detaylarıyla özel. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş.\nZINCIR: Kolye ucuyla birlikte Forse zincir verilir.\nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
