    "description": "Asteri \nAdını yıldızlardan alan, çizgisi net bir parıltı. Asteri’nin ince kabartıları ışığı yüzeyde yürütür; yaklaştıkça fark edilen küçük kırılmalar tasarıma ritim katar. Gösterişli olmadan dikkat çeken bu denge, beyaz gömlekle yalın; saten bir elbiseyle çarpıcı görünür. Ince zincirle zarif, daha dolgun bir zincirle heykelsi bir duruş verir. Güne gündelik bir ışıltı katmak ya da akşam görünümüne sakin bir vurgu eklemek istediğinde elin ilk gideceği parça. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş.\nZINCIR: Kolye ucuyla birlikte Forse zincir verilir.\nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
