    "description": "Êros \nBir oku gererken oluşan o gergin eğriyi düşün—Eros’un çizgisi tam da bu hissi taşır: hedefe odaklı, net ve çekici. Yüzeyindeki ince geçişler ışığı tek bir noktada patlatmak yerine boyunca dolaştırır; yaklaşınca fark edilen zarif bir hareket yaratır. Gösterişe yaslanmadan dikkat çeker: beyaz tişörtle cool, ipek bir elbiseyle çarpıcı. Büyük sözler söylemeden duyguyu üstünde taşımanın yolu; kendine ya da “o kişiye” verilmiş küçük ama etkisi yüksek bir jest. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş.\nZINCIR: Kolye ucuyla birlikte Forse zincir verilir.\nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
