    "short_description": "925 Ayar Gümüş 24k Altın Kaplama",
    "description": "Hræsvelgr \nKuzey mitlerindeki rüzgârları kanatlarında taşıyan dev kartalın adı… Hraesvelgr, akıcı ve keskinleşen hatlarıyla hareket ettikçe ışığı kanat çırpışı gibi kırar. Dingin ama güçlü silueti minimal görünümlere karakter katar; tek başına imza etkisi yaratırken, katmanlı stillerde grafik bir ritim kurar. Günün doğal akışında yalın ve zarif, akşam saatlerinde ise sofistike ve hatırlanır—Hraesvelgr, her ana serin bir esinti duygusu katar. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
