    "description": "Paen Seun \nSakin bir dalganın kıyıda bıraktığı iz gibi… Paen Seun, akışkan hatlarını zarif bir dengeyle birleştirerek bakışları nazikçe üzerine çeker. Hareket ettikçe canlılaşan yüzeyi sert bir parıltı yerine yumuşak bir ışıltı sunar; günlük kombinlerde doğal bir vurgu, akşam görünümlerinde ise sofistike bir final olur. Tek başına minimal bir imza taşıdığı gibi, farklı zincir ve dokularla katmanlandığında da karakterini çoğaltır. Mevsimden bağımsız, her güne “az ama öz” bir şıklık katar. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
