    "description": "Lisous \nYumuşak kıvrımları ve zarif asimetrisiyle sakin ama karakterli bir duruş sergiler. Işığı nazikçe toplayan yüzeyi hareket ettikçe canlı bir oyun yaratır; minimal kombinlerde dingin bir odak, daha iddialı stillerde ise sofistike bir tamamlayıcı olur. Gün boyu konforlu, mevsimden bağımsız ve zamansız—Lisous, gardırobunda “az sözle çok şey anlatan” imza parçan olmaya aday. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
