    "description": "Vidha \nDoğanın yumuşak kıvrımlarını modern bir çizgide yeniden yorumlayan Vidha, bakışları sessizce üzerine çeken zarif bir siluete sahip. Akıcı formu ışığı nazikçe yakalar; sade kombinlerde dingin bir odak, daha iddialı stillerde sofistike bir tamamlayıcı olur. Günün temposuna uyum sağlayan hafifliğiyle konforlu, zamansız karakteriyle de uzun yıllar gardırobun temel parçalarından biri olmaya aday. Şehirde hızlı bir gün ya da akşamın şık buluşmaları… Vidha, her ana doğal bir ışıltı ve ince bir zarafet katar. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş.\nZINCIR: Kolye ucuyla birlikte Forse zincir verilir.\nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
