    "short_description": "925 Ayar Gümüş 24k Altın Kaplama",
    "description": "Kauboy \nTozlu yolların özgürlük hissini şehir ritmiyle buluşturan modern bir yorum. Kauboy’un heykelsi silueti, lasso’yu hatırlatan akıcı bir kıvrımla başlar ve net bir konturda tamamlanır; ışık yüzeyde kayarken sert bir parıltı yerine sakin, kararlı bir ışıma bırakır. \nStil tarafında cesur ama ulaşılabilir: denim ceket ve beyaz tişörtle gündüz cool; siyah elbise ya da ipeksi dokularla akşam daha belirgin ve sofistike. Ince zincirle takıldığında zarif bir iz gibi durur; daha dolgun bir zincirle eşleştiğinde grafik ve iddialı bir vuruş yapar. \nGereksiz ayrıntılara değil, tutarlı bir ifadeye yaslanır. Kauboy, “yola çıkma” duygusunu günlük hayata taşıyan o parça: her takışta kendine güveni fısıldayan, modern ve zamansız bir imza. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
