    "description": "Sfâria \nIpeksi bir çizgi gibi boyundan kayıp giden, tertemiz bir akış… Sfâria’nın pürüzsüz halkaları ışığı keskinleştirmeden taşır; parlaklığı net, duruşu sakin. Göğüs hizasında ince bir kontur çizer ve silueti zarifçe uzatır. Kolye uçlarına eşlik ettiğinde tasarımı çerçeveler; tek başına kullanıldığında ise kusursuz bir çizgi etkisi yaratır. Basic bir tişörtte modern ve derli toplu, ipeksi dokularda heykelsi ve seçkin—günün her anına ayar tutan, “temiz” bir son dokunuş. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
