    "short_description": "925 Ayar Gümüş 24k Altın Kaplama Özel Tasarım Ile Istediğiniz Taş ve Renklerde Yapılabilir.",
    "description": "Özel Tasarım Ile Istediğiniz Taş ve Renklerde Yapılabilir. \nÖzel Tasarım Ürünlerimiz 10 / 15 Gün içinde Hazırlanıp Kargoya Verilir. \nEl Corazón \nKalbin en yalın çizgisi, süslenmeden anlatılan duygu. El Corazón, romantizmi klişeye düşürmeden taşıyan modern bir siluete sahip; dengeli konturu, ışığı yüzeyde dolaştırırken parıltıyı gösterişe değil derinliğe dönüştürür. Yakından bakıldığında görülen ince seviye farkları, elde biçimlendirilmiş o “gerçek” hissi verir—her takışta hatırayı diri tutan küçük bir ayrıntı.\nHediye etmek için kadar kişisel, her gün takmak için yeterince sakin. Tek başına saf bir odak yaratır; ince zincirlerle narin, daha dolgun zincirlerle heykelsi görünür. Istersen seçtiğin taş ve tonlarla kişiselleştirerek ona, kendine ya da bir anıya özel bir anlam katabilirsin. El Corazón, “söze gerek yok” dediğin anların zarif işareti.",
