    "short_description": "925 Ayar Gümüş 24k Altın Kaplama Kolye Ucunun Yanında Verilen Zincir : Forse Zincir",
    "description": "Kraken \nDerin denizin nabzı gibi, kıvrılıp çözülen bir hareket… Kraken’in heykelsi formu, dalga ve tentakül çağrışımlarını modern bir çizgide toplar. Yüzeyindeki ince geçişler ışığı tek noktada parlatmak yerine boyunca gezdirir; uzaktan güçlü, yakından detaylı bir etki bırakır. Gündüz denimle cool ve özgür, akşam koyu tonlarla çarpıcı bir kontrast yaratır. Tek başına iddialı bir merkez, katmanlandığında görünümün ritmini belirleyen kararlı bir imza. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
