    "description": "Özel Tasarım Ile Istediğiniz Taş ve Renklerde Yapılabilir. \nÖzel Tasarım Ürünlerimiz 10 / 15 Gün içinde Hazırlanıp Kargoya Verilir. \nSekìâ Ring \nTek nefeste çizilmiş gibi duran, kararlı bir kavis… Sekìâ’nın heykelsi formu parmakta akıp giden bir hat oluşturur; yüzeyindeki ince geçişler ışığı boydan boya gezdirir, parıltısı göz almaz—derin ve sakin. Dengeli asimetrisi sayesinde hem zarif hem iddialıdır: keskin bir gömlek manşetinin altında sofistike, ipeksi bir elbiseyle çarpıcı bir finale dönüşür.\nTek başına net bir imza bırakır; dokulu ince bantlarla “stack” yapıldığında modern bir ritim kurar. Uzun yıllar modası geçmeyecek, fazla söz istemeyen bir karakter: Sekìâ, görünümüne tek hamlede ölçülü güç katar.",
