    "short_description": "925 Ayar Gümüş Kolye Ucunun Yanında Verilen Zincir : Forse Zincir",
    "description": "mâ \nBir damlanın bıraktığı en sade iz… mâ, yumuşak bir eğriyle boyunda doğal bir akış kurar; yüzeyi ışığı nazikçe dağıtarak temiz, sakin bir parıltı verir. Gömlek yakasında düzenli ve ölçülü, açık yakalarda daha belirgin durur; ince zincirle hafif, daha dolgun zincirle heykelsi bir etki kazandırır. Günün temposuna uyumlu, dikkat çekmek için bağırmayan; kendine ya da yakın birine düşünceli bir jest olacak kadar da özel. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
