    "description": "Dêva \nAdı gibi ferahlatan, nefes açan bir çizgi. Dêva’nın akıcı kavsi boyunda doğal bir yol çizer; yüzeyindeki ince seviye farkları ışığı tek noktada patlatmak yerine yedirerek sakin bir ışıma yaratır. Uzaktan berrak ve düzenli, yaklaştıkça el işçiliğini hissettiren detaylı bir ifade… Monokrom bir takımı yumuşatır, ince askılı bir bluzla daha zarif ve narin görünür. Şekli “fazlasız” şıklığın özetidir: abartıya başvurmadan dikkat çeker, her günün ritmine uyum sağlar. Kendi temposunu bulmak isteyenler için ince ama kararlı bir imza. \nMALZEME: 925 ayar gümüş gövde. \nRENK: Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
