    "description": "sirā \nTek bir fırça darbesi gibi boyunda akıp giden, net ama yumuşak bir çizgi. sirā, ışığı sertçe patlatmak yerine yüzey boyunca dolaştırır; hareket ettikçe sakin bir parıltı belirir. Gömlek yakasının altında ölçülü ve derli toplu, açık yaka üzerinde ise daha belirgin bir duruş sergiler. Tek başına yalın bir vurgu yaratır; farklı kalınlıktaki zincirlerle üst üste kullanıldığında görünümü ritimlendiren modern bir merkez noktası olur. Fazlasız, zamansız, güvenilir—her gün takmak isteyeceğin o parça. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
