    "description": "Stârâ \nYıldızın keskin ışığını yumuşak bir çizgide yeniden kurar. Ince kabartıları ışığı tek noktada patlatmak yerine yüzeyde dolaştırır; uzaktan berrak, yakından detaylı bir parıltı görürsün. Beyaz tişörtle ferah, saten bir elbiseyle seçkin; V yaka ve kayık yaka formlarını zarifçe uzatır. Katmanlandığında diğer zincirlerle ritim yakalayan Stârâ, gündüz sakin bir ışıltı, akşam ise hatırlanır bir vurgu bırakır—boynunda gökyüzünden küçük bir işaret gibi. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
