    "description": "The Sea’s Trace Necklace \nGeri çekilen dalganın kumda bıraktığı o ince, ritimli iz… Sea’s Trace bu hissi yumuşak bir kıvrımla boynuna taşır. Yüzeyindeki sakin dokunuşlar ışığı tek noktada patlatmak yerine boyunca gezdirir; hareket ettikçe canlı ama zarif bir parıltı ortaya çıkar. Yakından bakıldığında fark edilen küçük kırılmalar, tasarıma deniz esintisi gibi hafif bir dinamizm katar. \nStil tarafında esnektir: beyaz gömlekle taze ve yalın, satenle akşam saatlerinde daha derin bir ifade. Tek başına temiz bir odak yaratır; farklı kalınlıktaki zincirlerle yan yana geldiğinde görünümü zenginleştirir. Mevsimden bağımsız, “fazlasız” şıklığın denizle buluştuğu parça—kıyı çizgisinin sakinliğini her güne taşır. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama veya Gümüş. \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
