    "description": "The Gem Eye Necklace \nAntik sembolizmin gücünü modern zarafetle buluşturan The Gem Eye Necklace ile tanışın. Bu büyüleyici kolye, stilinize derinlik katarken, yüzyıllardır süregelen 'Nazar Boncuğu' (Evil Eye) inancının koruyucu enerjisini de üzerinizde taşımanızı sağlar. \nMALZEME: 925 ayar gümüş gövde, 24k altın kaplama seçeneği mevcut. \nRENK: Altın Kaplama \nZINCIR: Kolye ucuyla birlikte Forse zincir verilir. \nBAKIM TALIMATLARI: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
