    "description": "Çağlar boyu süren bir hikaye, tek bir formda mühürlendi. \nOval tasarımıyla sonsuzluğu simgeleyen The Eon Ring , Ruth Istanbul’un geçmişin tozlu sayfalarından günümüze taşıdığı en özel parçalardan biri. Üzerindeki hiyeroglif figürler, sanki binlerce yıl önce bir mühürle basılmışçasına canlı ve karizmatik duruyor.\nMateryal: 925 Ayar Gümüş üzerine 24 Ayar Altın Kaplama.\nTasarım: Antik mühür yüzüklerinden ilham alan oval tabla ve üzerinde titizlikle işlenmiş semboller.\nDoku: Güneşin sıcaklığını yansıtan parlak altın.\nUyum: Ayarlanabilir yapısı sayesinde hem işaret hem de yüzük parmağınızda konforlu bir kullanım sunar.\nNeden Seçmelisin? The Eon Ring, sadece bir aksesuar değil; zamanın ötesinden gelen bir tılsım gibi stilinizi tamamlar. Oval hatları sayesinde parmağınızda daha ince ve zarif bir görünüm oluştururken, siyah işlemeleriyle iddialı bir kontrast yaratır. Modern dünya ile antik çağlar arasında bir köprü kurmak isteyenler için tasarlandı.\n\"Zaman geçer, stiliniz çağlar boyu (eon) kalır.\"",
