    "short_description": "Zarafetin en net ifadesi, antik çağların modern ikonu. Koleksiyonun en ince ve şık detaylı parçalarından biri olan The Icon Ring , yatay formuyla parmakta eşsiz bir silüet oluşturuyor. Üzerindeki hiyeroglif karakterleri, sanki kaybolmuş bir şehirden günümüze…",
    "description": "Zarafetin en net ifadesi, antik çağların modern ikonu. \nKoleksiyonun en ince ve şık detaylı parçalarından biri olan The Icon Ring , yatay formuyla parmakta eşsiz bir silüet oluşturuyor. Üzerindeki hiyeroglif karakterleri, sanki kaybolmuş bir şehirden günümüze ulaşan küçük bir yazıt gibi parlıyor. Minimalist yapısı, onu her gün takmak isteyeceğiniz zamansız bir ikon haline getiriyor.\nMateryal: 925 Ayar Gümüş / 24 Ayar Altın Kaplama.\nTasarım: Ince, yatay dikdörtgen tabla üzerinde kontrast yaratan siyah sembol işlemeleri.\nDoku: Parlak altın dokusuyla güneşten bir parça gibi parlar.\nUyum: Arkası açık, ayarlanabilir tasarımı sayesinde her parmağa göre kişiselleştirilebilir.\nNeden Seçmelisin? The Icon Ring, \"az ama öz\" diyenlerin tercihi. Yatay yerleşimi sayesinde parmağınızın doğal formuna uyum sağlar ve diğer yüzüklerle bir arada kullanıldığında estetik bir denge oluşturur. Hem gündüz hem gece şıklığında, sessiz ama güçlü bir tarzın simgesidir.\n\"Bir ikon, asla modası geçmeyen bir hikayedir.\"",
