    "short_description": "Üç farklı form, tek bir kadim hikaye. Ruth Istanbul’un \"Sun-Kissed: Bölüm II\" koleksiyonunun en güçlü üç karakteri, bu özel sette bir araya geliyor. Kare formun netliğiyle The Sign , oval hatların sonsuzluğuyla The Eon ve yatay zarafetiyle The Icon ;…",
    "description": "The Trilogy Of Sun: Antik Formlar Seti \nÜç farklı form, tek bir kadim hikaye. \nRuth Istanbul’un \"Sun-Kissed: Bölüm II\" koleksiyonunun en güçlü üç karakteri, bu özel sette bir araya geliyor. Kare formun netliğiyle The Sign , oval hatların sonsuzluğuyla The Eon ve yatay zarafetiyle The Icon ; parmaklarınızda zamansız bir denge kurmak için tasarlandı.\nAntik hiyerogliflerin mistik dokusunu modern bir stack (üst üste dizim) sanatına dönüştüren bu set, stilinde derinlik ve anlam arayanlar için kürate edildi.\nSet Içeriği: \nThe Sign Ring: Gücü simgeleyen kare form ve hiyeroglif yazıtlar.\nThe Eon Ring: Sonsuzluğu temsil eden oval mühür tasarımı.\nThe Icon Ring: Zarafeti tamamlayan yatay ve ince ikonik duruş.\nÖzellikler: \nMateryal: Tamamı 925 Ayar Gümüş üzerine 24 Ayar Altın Kaplama.\nTasarım: Mat,parlak doku ve özel siyah oksit işleme detaylar.\nUyum: Tüm yüzükler ayarlanabilir formdadır, her parmak ölçüsüne uyum sağlar.\nNeden Bu Seti Seçmelisin? Bu üçlü seçki, tek tek alımlara göre avantajlı bir fiyat sunarken, sizi \"neyle neyi kombinlemeliyim?\" sorusundan kurtarır. Ister üçünü aynı anda farklı parmaklarınızda taşıyarak iddialı bir \"Antique Stack\" görünümü yaratın, istersen günün enerjisine göre parçaları tekli kullanın.\n\"Geçmişin sembollerini bugünün ışığıyla birleştirin. Kendi hikayenizi mühürleme zamanı.\"",
