    "description": "The Midnight Hour Necklace \nGece gökyüzünden ilham alan The Midnight Hour Necklace , siyah zemin üzerine işlenen ay, güneş ve yıldız detaylarıyla zamansız bir görünüm sunar. Altın rengi çerçevesi ve parlak yüzeyiyle hem günlük kombinlerde hem de özel anlarda dikkat çeken mistik bir parça.\nKum saati formu, zamanı ve dönüşümü simgelerken; gökyüzü motifleri kolyeye güçlü ve anlamlı bir karakter kazandırır. Minimal ama etkileyici tasarımıyla tek başına kullanıldığında da katmanlı kolye kombinlerinde de şık bir duruş sağlar.\nMalzeme : Brass Gövde, 24K Altın Kaplama\nZincir: Kolye ucunun yanında 925 Ayar Gümüş Forse Zincir gönderilir. \nBakım Talimatları: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
