    "description": "The Nazar Ring Set \nNazar boncuğunun koruyucu enerjisinden ilham alan The Nazar Ring Set , iki farklı yüzük tasarımını bir araya getiren zarif ve dikkat çekici bir settir.\nSetin içinde yer alan klasik nazar detaylı yüzük, parlak taş dokunuşuyla şık bir görünüm sunarken; burgu formlu yüzük tasarıma daha modern ve güçlü bir hava katar. Altın tonlu ışıltısı ve mavi nazar detaylarıyla günlük kombinlerden özel davetlere kadar her stile kolayca uyum sağlar.\nTek tek kullanıldığında sade ve zarif, birlikte takıldığında ise daha iddialı ve tamamlayıcı bir görünüm oluşturur.\nMALZEME: 925 Ayar Gümüş üzeri 14 Ayar Altın Kaplama\nDIKKAT EDILMESI GEREKENLER: Parlaklığını korumak için sıvı parfüm/dezenfektanla uzun süreli temastan kaçın, kullanmadığın zamanlarda size göndereceğimiz kapalı Ruth Istanbul kutusunda sakla.",
